flashExtractionPrompt.responseSchema:
{
  "type": "object",
  "description": "Companion extraction output — field mappings, modifiers, intent",
  "required": ["intent", "mappedFields", "unmappedFields", "modifiers"],
  "properties": {

    "intent": {
      "type": "string",
      "description": "Per-turn intent classification. Must match the conversation prompt's intent for backend merge consistency.",
      "enum": ["DATA_INPUT", "WHAT_IF", "CORRECTION", "QUESTION", "GOAL_CHANGE", "GOAL_QUERY", "GREETING", "ACKNOWLEDGMENT"]
    },

    "mappedFields": {
      "type": "array",
      "description": "Fields extracted and successfully mapped to canonical schema. Empty array if no mappable data was provided.",
      "items": {
        "type": "object",
        "required": ["key", "rawSpan", "confidenceScore"],
        "properties": {
          "key": {
            "type": "string",
            "description": "Best guess key of the parsed field. Canonical field key from fieldSchema (e.g., 'monthlyIncome')"
          },
          "value": {
            "type": "string",
            "description": "Value of the parsed field in its raw representation. NOT multiplied or transformed. '1.2' not '120000'. For dates, ISO 8601 when possible. Integers stay integers ('3' not '3.0'). Max 16 characters.",
            "nullable": true,
            "maxLength": 16
          },
          "type": {
            "type": "string",
            "description": "Best guess type of the parsed field",
            "enum": ["TEXT", "NUMBER", "DATE"]
          },
          "rawUnit": {
            "type": "string",
            "description": "Scale or unit word as spoken: lakh, thousand, K, crore, hazaar, years, months. Null if no scale/unit word used.",
            "nullable": true
          },
          "period": {
            "type": "string",
            "description": "Temporal basis. Null if not applicable.",
            "enum": ["MONTHLY", "ANNUAL", "WEEKLY", "DAILY", "ONE_TIME"],
            "nullable": true
          },
          "qualifier": {
            "type": "string",
            "description": "Null if unambiguous.",
            "enum": ["APPROXIMATE", "RANGE", "EXACT"],
            "nullable": true
          },
          "rawSpan": {
            "type": "string",
            "description": "Exact user phrase this extraction came from"
          },
          "relationship": {
            "type": "string",
            "description": "Who this data belongs to. Null if SELF.",
            "enum": ["SELF", "SPOUSE", "PARENT", "CHILD"],
            "nullable": true
          },
          "inferredValue": {
            "type": "string",
            "description": "Resolved interpretation of the value after applying context. For relative dates, implicit references, or ambiguous expressions. Null when value is already unambiguous. Max 16 characters.",
            "nullable": true,
            "maxLength": 16
          },
          "confidenceScore": {
            "type": "string",
            "description": "Confidence in the key mapping",
            "enum": ["HIGH", "MEDIUM", "LOW"]
          }
        }
      }
    },

    "unmappedFields": {
      "type": "array",
      "description": "Data the user provided that could not be mapped to any canonical or JIT field. Uses the same schema as mappedFields for uniform backend processing. The key value is the Companion's best-guess descriptive key.",
      "items": {
        "type": "object",
        "required": ["key", "rawSpan", "confidenceScore"],
        "properties": {
          "key": {
            "type": "string",
            "description": "Best-guess descriptive key (e.g., 'spouseIncome', 'sideHustleRevenue', 'carLoanRemaining'). NOT a canonical field — backend decides disposition."
          },
          "value": {
            "type": "string",
            "description": "Value of the parsed field in its raw representation. NOT multiplied or transformed. Integers stay integers. Max 16 characters.",
            "nullable": true,
            "maxLength": 16
          },
          "type": {
            "type": "string",
            "description": "Best guess type of the parsed field",
            "enum": ["TEXT", "NUMBER", "DATE"]
          },
          "rawUnit": {
            "type": "string",
            "description": "Scale or unit word as spoken. Null if none.",
            "nullable": true
          },
          "period": {
            "type": "string",
            "description": "Temporal basis if mentioned. Null if unknown.",
            "enum": ["MONTHLY", "ANNUAL", "WEEKLY", "DAILY", "ONE_TIME"],
            "nullable": true
          },
          "qualifier": {
            "type": "string",
            "description": "Null if unambiguous.",
            "enum": ["APPROXIMATE", "RANGE", "EXACT"],
            "nullable": true
          },
          "rawSpan": {
            "type": "string",
            "description": "Exact user phrase"
          },
          "relationship": {
            "type": "string",
            "description": "Who this data belongs to. Null if SELF/unspecified.",
            "enum": ["SELF", "SPOUSE", "PARENT", "CHILD"],
            "nullable": true
          },
          "inferredValue": {
            "type": "string",
            "description": "Resolved interpretation of the value. Null when value is already unambiguous. Max 16 characters.",
            "nullable": true,
            "maxLength": 16
          },
          "confidenceScore": {
            "type": "string",
            "description": "Confidence in the best-guess key",
            "enum": ["HIGH", "MEDIUM", "LOW"]
          }
        }
      }
    },

    "modifiers": {
      "type": "array",
      "description": "What-if modifications to existing fields. Each modifier references a canonical field and describes a delta operation. For COMPARE operations, emit one modifier per alternative — all sharing the same compareGroup value.",
      "items": {
        "type": "object",
        "required": ["targetField", "operation", "rawSpan"],
        "properties": {
          "targetField": {
            "type": "string",
            "description": "Canonical field being modified (e.g., 'monthlySavings')"
          },
          "operation": {
            "type": "string",
            "description": "What the user wants to do",
            "enum": ["INCREASE", "DECREASE", "REPLACE", "REMOVE", "INCREASE_PERCENT", "DECREASE_PERCENT", "COMPARE"]
          },
          "value": {
            "type": "string",
            "description": "Delta value in raw representation, not multiplied. Max 16 characters.",
            "nullable": true,
            "maxLength": 16
          },
          "type": {
            "type": "string",
            "description": "Type of the modifier value",
            "enum": ["TEXT", "NUMBER", "DATE"]
          },
          "rawUnit": {
            "type": "string",
            "description": "Scale or unit word for the delta",
            "nullable": true
          },
          "period": {
            "type": "string",
            "enum": ["MONTHLY", "ANNUAL", "WEEKLY", "DAILY", "ONE_TIME"],
            "nullable": true
          },
          "rawSpan": {
            "type": "string",
            "description": "Exact user phrase"
          },
          "inferredValue": {
            "type": "string",
            "description": "Resolved interpretation of the delta value. Null when value is already unambiguous. Max 16 characters.",
            "nullable": true,
            "maxLength": 16
          },
          "compareGroup": {
            "type": "string",
            "description": "Identifier linking modifiers that belong to the same comparison. Only present when operation is COMPARE. All alternatives in a single comparison share the same compareGroup value. Use a descriptive camelCase slug (e.g., 'savingsComparison').",
            "nullable": true
          }
        }
      }
    }
  }
}
